/* ─────────────────────────────────────────────────────────────
   HELPERS
───────────────────────────────────────────────────────────── */
function useInView(th = 0.1) {
  const r = useRef(null); const [v, sv] = useState(false);
  useEffect(() => {
    const el = r.current; if (!el) return;
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { sv(true); obs.disconnect(); } }, { threshold: th });
    obs.observe(el); return () => obs.disconnect();
  }, [th]);
  return [r, v];
}

function Rev({ children, delay = 0, type = "fadeUp", style = {} }) {
  const [r, v] = useInView();
  const A = {
    fadeUp:  "fadeUp .65s ease both",
    fadeIn:  "fadeIn .6s ease both",
    slideR:  "slideR .65s ease both",
    slideL:  "slideL .65s ease both",
    scaleIn: "scaleIn .55s ease both",
    cardEntrance: "cardEntrance .6s ease both",
  };
  return (
    <div ref={r} style={{ opacity:v?undefined:0, animation:v?A[type]:"none", animationDelay:v?`${delay}ms`:"0ms", ...style }}>
      {children}
    </div>
  );
}

/* ── TYPEWRITER ── */
function Typewriter({ words, speed = 72, pause = 1900 }) {
  const [disp, sd] = useState(""); const [wi, sw] = useState(0);
  const [ci, sc] = useState(0); const [del, sdel] = useState(false);
  useEffect(() => {
    const w = words[wi]; let tm;
    if (!del && ci < w.length)      tm = setTimeout(() => sc(c=>c+1), speed);
    else if (!del && ci===w.length) tm = setTimeout(() => sdel(true), pause);
    else if (del && ci > 0)         tm = setTimeout(() => sc(c=>c-1), speed/2);
    else { sdel(false); sw(i=>(i+1)%words.length); }
    sd(w.slice(0,ci)); return () => clearTimeout(tm);
  }, [ci,del,wi,words,speed,pause]);
  return (
    <span>
      {disp}
      <span style={{ color:T.goldMd, animation:"blink 1s step-end infinite" }}>|</span>
    </span>
  );
}

/* ── STAR FIELD (hero background) ── */
function Stars() {
  const stars = useRef(
    Array.from({ length: 80 }, (_, i) => ({
      id: i,
      x: Math.random() * 100,
      y: Math.random() * 100,
      size: Math.random() * 2 + 0.5,
      delay: Math.random() * 4,
      dur: 2.5 + Math.random() * 3,
    }))
  ).current;
  return (
    <div style={{ position:"absolute", inset:0, pointerEvents:"none", overflow:"hidden" }}>
      {stars.map(s => (
        <div key={s.id} style={{
          position:"absolute", left:`${s.x}%`, top:`${s.y}%`,
          width:s.size, height:s.size, borderRadius:"50%",
          background:T.goldLt, opacity:.25,
          animation:`starTwinkle ${s.dur}s ease-in-out ${s.delay}s infinite`,
        }} />
      ))}
    </div>
  );
}

