/* ─────────────────────────────────────────────────────────────
   NAVBAR
───────────────────────────────────────────────────────────── */
function Navbar({ srefs }) {
  const [scrolled, ss] = useState(false);
  const [active,   sa] = useState("home");

  const go = useCallback((id) => {
    (srefs[id]?.current || document.getElementById(id))?.scrollIntoView({ behavior:"smooth", block:"start" });
  }, [srefs]);

  useEffect(() => {
    const IDS = ["home","about","skills","projects","education","certificates","contact"];
    const fn = () => {
      ss(window.scrollY > 60);
      for (let i=IDS.length-1; i>=0; i--) {
        const el = srefs[IDS[i]]?.current || document.getElementById(IDS[i]);
        if (el && window.scrollY + 150 >= el.offsetTop) { sa(IDS[i]); break; }
      }
    };
    window.addEventListener("scroll", fn, { passive:true });
    return () => window.removeEventListener("scroll", fn);
  }, [srefs]);

  const LINKS = ["home","about","skills","projects","education","certificates","contact"];

  return (
    <nav style={{
      position:"fixed", top:0, left:0, right:0, zIndex:300,
      background: scrolled ? "rgba(7,11,22,.97)" : "transparent",
      backdropFilter: scrolled ? "blur(18px)" : "none",
      borderBottom: scrolled ? `1px solid ${T.border}` : "1px solid transparent",
      transition:"all .35s ease",
      animation:"navSlideIn .6s ease both",
    }}>
      <div className="nav-in" style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"1.1rem 4rem", maxWidth:1300, margin:"0 auto" }}>
        {/* Logo */}
        <button onClick={()=>go("home")} style={{ background:"none", border:"none", cursor:"pointer" }}>
          <span style={{
            fontFamily:"Cormorant Garamond,serif", fontSize:"1.6rem", fontWeight:700,
            background:`linear-gradient(135deg,${T.gold},${T.goldLt})`,
            WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent",
          }}>SH<span style={{ WebkitTextFillColor:T.ink2 }}>.</span></span>
        </button>

        <div className="nav-lks" style={{ display:"flex", gap:"2rem", alignItems:"center" }}>
          {LINKS.map(id => (
            <button key={id} className={`nl${active===id?" act":""}`} onClick={()=>go(id)}>
              {id.charAt(0).toUpperCase()+id.slice(1)}
            </button>
          ))}
        </div>
      </div>
    </nav>
  );
}

