/* ─────────────────────────────────────────────────────────────
   CONTACT
───────────────────────────────────────────────────────────── */
function Contact({ sref }) {
  const [form, sf] = useState({ name:"", email:"", message:"" });
  const [status, ss] = useState(null);

  const [sending, setSending] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.message) { ss("err"); return; }
    setSending(true);
    // Build mailto link — opens default email client pre-filled
    const subject = encodeURIComponent(`Portfolio Enquiry from ${form.name}`);
    const body = encodeURIComponent(
      `Hi Harshita,\n\nYou have a new message from your portfolio:\n\nName: ${form.name}\nEmail: ${form.email}\n\nMessage:\n${form.message}\n\n---\nSent from Portfolio Contact Form`
    );
    const mailtoLink = `mailto:harshita.kondamuri@gmail.com?subject=${subject}&body=${body}`;
    // Create hidden anchor and trigger it (more reliable than window.open)
    const a = document.createElement("a");
    a.href = mailtoLink;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => {
      setSending(false);
      ss("ok");
      sf({ name:"", email:"", message:"" });
    }, 800);
  };

  const INFO = [
    {icon:"✉",label:"Email",    value:"harshita.kondamuri@gmail.com",href:"mailto:harshita.kondamuri@gmail.com"},
    {icon:"in",label:"LinkedIn", value:"sri-harshita-kondamuri",       href:"https://www.linkedin.com/in/sri-harshita-kondamuri/"},
    {icon:"⌨",label:"GitHub",   value:"Sriharshita05",                href:"https://github.com/Sriharshita05"},
    {icon:"📱",label:"Phone",    value:"+91 93814 15639",              href:"tel:+919381415639"},
    {icon:"📍",label:"Location", value:"Phagwara, Punjab, India",      href:"#"},
  ];

  return (
    <section id="contact" ref={sref} className="sec" style={{ background:T.bg2, borderTop:`1px solid ${T.border}` }}>
      <div style={{ maxWidth:1300, margin:"0 auto" }}>
        <SecHead eyebrow="Get In Touch" title="Contact Me" center />
        <div className="contact-g" style={{ display:"grid", gridTemplateColumns:"1fr 1.3fr", gap:"4rem", alignItems:"start" }}>
          {/* LEFT */}
          <div>
            <Rev type="slideR">
              <h3 style={{ fontFamily:"Cormorant Garamond,serif", fontSize:"1.65rem", fontWeight:700, color:T.ink, marginBottom:"1rem", lineHeight:1.3 }}>
                Let's{" "}
                <span style={{ background:`linear-gradient(135deg,${T.gold},${T.goldLt})`, WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent" }}>build something</span>{" "}
                remarkable
              </h3>
              <p style={{ fontFamily:"Outfit,sans-serif", fontSize:"14px", color:T.ink2, lineHeight:1.85, marginBottom:"2rem" }}>
                Open to internships, freelance projects, and full-time roles. Have a project in mind? Let's connect and make it happen.
              </p>
            </Rev>
            <div style={{ display:"flex", flexDirection:"column", gap:".35rem" }}>
              {INFO.map((c,i) => (
                <Rev key={c.label} delay={80+i*65} type="slideR">
                  <a href={c.href} target={c.href.startsWith("http")?"_blank":"_self"} rel="noreferrer"
                    style={{ display:"flex", alignItems:"center", gap:".85rem", textDecoration:"none", padding:".65rem .75rem", borderRadius:8, transition:"background .2s" }}
                    onMouseEnter={e=>e.currentTarget.style.background=T.goldGlow2}
                    onMouseLeave={e=>e.currentTarget.style.background="transparent"}
                  >
                    <div style={{ width:38, height:38, borderRadius:9, background:T.surface, border:`1px solid ${T.border}`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:"15px", flexShrink:0, transition:"all .2s" }}
                      onMouseEnter={e=>{e.currentTarget.style.background=T.gold;e.currentTarget.style.color=T.bg0;}}
                      onMouseLeave={e=>{e.currentTarget.style.background=T.surface;}}
                    >{c.icon}</div>
                    <div>
                      <div style={{ fontFamily:"JetBrains Mono,monospace", fontSize:"9.5px", color:T.muted, letterSpacing:".1em", textTransform:"uppercase" }}>{c.label}</div>
                      <div style={{ fontFamily:"Outfit,sans-serif", fontSize:"13.5px", fontWeight:600, color:T.ink }}>{c.value}</div>
                    </div>
                  </a>
                </Rev>
              ))}
            </div>
            <Rev delay={520}>
              <div style={{ background:T.surface, border:`1px solid ${T.gold}44`, borderRadius:8, padding:"1rem 1.25rem", marginTop:"1.5rem", display:"flex", alignItems:"center", gap:".6rem", boxShadow:`0 0 14px ${T.goldGlow}` }}>
                <span style={{ fontSize:"16px" }}>⏱</span>
                <span style={{ fontFamily:"JetBrains Mono,monospace", fontSize:"11px", color:T.goldMd }}>Usually responds within 24 hours</span>
              </div>
            </Rev>
          </div>

          {/* RIGHT — form */}
          <Rev type="slideL" delay={100}>
            <div style={{ background:T.surface, border:`1px solid ${T.border}`, borderRadius:14, padding:"2.5rem", boxShadow:`0 24px 72px rgba(0,0,0,.45), 0 0 0 1px ${T.gold}18` }}>
              <h4 style={{ fontFamily:"Cormorant Garamond,serif", fontSize:"1.3rem", fontWeight:700, color:T.ink, marginBottom:"1.75rem" }}>Send a message</h4>
              <div className="form-row" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:"1rem", marginBottom:"1rem" }}>
                <div>
                  <label style={{ fontFamily:"JetBrains Mono,monospace", fontSize:"10px", color:T.muted, letterSpacing:".1em", textTransform:"uppercase", display:"block", marginBottom:".4rem" }}>Name *</label>
                  <input value={form.name} onChange={e=>sf(f=>({...f,name:e.target.value}))} placeholder="Your name" className="form-input"/>
                </div>
                <div>
                  <label style={{ fontFamily:"JetBrains Mono,monospace", fontSize:"10px", color:T.muted, letterSpacing:".1em", textTransform:"uppercase", display:"block", marginBottom:".4rem" }}>Email *</label>
                  <input type="email" value={form.email} onChange={e=>sf(f=>({...f,email:e.target.value}))} placeholder="your@email.com" className="form-input"/>
                </div>
              </div>
              <div style={{ marginBottom:"1.5rem" }}>
                <label style={{ fontFamily:"JetBrains Mono,monospace", fontSize:"10px", color:T.muted, letterSpacing:".1em", textTransform:"uppercase", display:"block", marginBottom:".4rem" }}>Message *</label>
                <textarea value={form.message} onChange={e=>sf(f=>({...f,message:e.target.value}))} placeholder="Tell me about your project or opportunity…" className="form-input"/>
              </div>
              {status==="err" && <div style={{ fontFamily:"Outfit,sans-serif", fontSize:"12px", color:"#ef4444", marginBottom:"1rem", padding:".5rem .8rem", background:"#1a0808", borderRadius:6, border:"1px solid #7f1d1d" }}>Please fill in all required fields.</div>}
              {status==="ok"  && <div style={{ fontFamily:"Outfit,sans-serif", fontSize:"12px", color:T.green, marginBottom:"1rem", padding:".5rem .8rem", background:"#081a10", borderRadius:6, border:"1px solid #14532d" }}>Email client opened — thank you for reaching out!</div>}
              <button onClick={handleSubmit} className="btn-gold" style={{ width:"100%", justifyContent:"center", padding:".9rem", opacity:sending?0.7:1, cursor:sending?"not-allowed":"pointer" }} disabled={sending}>{sending ? "Opening Email Client…" : "Send Message →"}</button>
              <p style={{ fontFamily:"JetBrains Mono,monospace", fontSize:"10px", color:T.muted, textAlign:"center", marginTop:".85rem" }}>Opens your default email client.</p>
            </div>
          </Rev>
        </div>
      </div>
    </section>
  );
}

